import json, re, os

APP = "/home/hatch/workspace/qr-site/assets/js/app.js"
s = open(APP).read()

def js_lang(code, d):
    parts = []
    for k, v in d.items():
        parts.append(f"{k}:{json.dumps(v, ensure_ascii=False)}")
    return f"{code}:{{{','.join(parts)}}}"

